OUT: list[str] = []
CHECK: dict = {}


def chunk(cid: str, title: str, source: str, tags: str, body) -> None:
    OUT.append(f"### [CHUNK {cid}] {title} | source: {source} | tags: {tags}")
    OUT.extend(body if isinstance(body, list) else [body])
    OUT.append("")


def fnum(x, nd=3):
    try:
        v = float(x)
    except (TypeError, ValueError):
        return None
    return None if math.isnan(v) else round(v, nd)


def gv(x, unit="", nd=3) -> str:
    """Value with unit for the per-test chunks; blank cells read 'not given'."""
    v = fnum(x, nd)
    if v is None:
        return "not given"
    return f"{v} {unit}".strip()


def resp(x) -> str:
    """Response time in s, or 'no response within 900 s' when blank."""
    v = fnum(x, 0)
    return f"{v:.0f} s" if v is not None else "no response within 900 s"


def load_json(p):
    return json.loads(Path(p).read_text(encoding="utf-8-sig"))


def read_csv(p):
    with open(p, encoding="utf-8-sig", newline="") as fh:
        return list(csv.DictReader(fh))


def findings() -> list[dict]:
    fs = []
    for f in sorted(T3.glob("PSI-*/findings.md")):
        for line in f.read_text(encoding="utf-8").splitlines():
            if line.startswith("F-T3-"):
                p = [x.strip() for x in line.split("|")]
                if len(p) == 7:
                    fs.append(dict(id=p[0], statement=p[1], label=p[2], source=p[3], rows=p[4], confidence=p[5],
                                   caveat=p[6], record=f.parent.name.split("_")[0]))
    return sorted(fs, key=lambda d: int(d["id"].split("-")[-1]))


def hatch_choate_check(tests) -> None:
    n = ok1 = ok3 = 0
    for r in tests:
        try:
            amd, sg, dg, dam = (float(r[k]) for k in ("mean_diam_um", "sigma_g", "dg_um", "diam_avg_mass_um"))
        except ValueError:
            continue
        if amd <= 0 or sg <= 1 or dg <= 0:
            continue
        n += 1
        ok1 += abs(dg * math.exp(0.5 * math.log(sg) ** 2) / amd - 1) < 0.02
        ok3 += abs(dg * math.exp(1.5 * math.log(sg) ** 2) / dam - 1) < 0.02
    CHECK.update(n=n, ok1=ok1, ok3=ok3)


