    # ---------------------------------------------------------------- per material
    rows = [r for r in tests if (fnum(r["mean_diam_um"]) or 0) > 0 and r.get("size_consistent") != "False"]
    for mat in ["Kapton", "Teflon", "Lampwick", "Pyrell", "Silicone"]:
        body = [f"Material {mat} in SAME (2007) and SAME-R (2010) flight tests (source S7; Excel rows given; rows kept out by F-T3-23 are not counted). Never pool the two flights. [CALC]"]
        for mission in ["SAME", "SAME-R"]:
            mr = [r for r in rows if r["material"] == mat and r["mission"] == mission]
